import 'package:hyzen_pharmd/features/pdf_studio/presentation/rich_document_screen.dart';

class _ScanStorage implements StudioStorage {
  @override
  Future<StoredStudioFile> importCopy(String sourcePath,String id)async=>StoredStudioFile(path:'/private/$id.pdf',editStatePath:'/private/${id}_state.json',sizeBytes:1234,extension:'pdf');
  @override
  Future<bool> exists(String path)async=>true;
  @override
  Future<void> deleteStored({required String path,required String editStatePath})async{}
}

void main(){
  TestWidgetsFlutterBinding.ensureInitialized();
  late Directory directory;
  setUp(()async{
    directory=await Directory.systemTemp.createTemp('hyzen-scan-test-');Hive.init(directory.path);
    await Hive.openBox<String>(Boxes.pdfStudioHistory);
  });
  tearDown(()async{
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMethodCallHandler(const MethodChannel('com.hyzen.pharmd/document_scanner'),null);
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMethodCallHandler(const MethodChannel('com.hyzen.pharmd/pdf_studio'),null);
    await Hive.close();await directory.delete(recursive:true);
  });
  testWidgets('cancelled scan does not create an offline document',(tester)async{
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMethodCallHandler(const MethodChannel('com.hyzen.pharmd/document_scanner'),(_)async=>null);
    await tester.pumpWidget(const ProviderScope(child:MaterialApp(home:ScanPdfScreen())));
    await tester.tap(find.text('Scan with camera'));await tester.pumpAndSettle();
    expect(find.text('Save PDF'),findsNothing);expect(Hive.box<String>(Boxes.pdfStudioHistory).isEmpty,isTrue);
  }, variant:TargetPlatformVariant.only(TargetPlatform.android));
  testWidgets('successful scan offers a named PDF and page count',(tester)async{
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMethodCallHandler(const MethodChannel('com.hyzen.pharmd/document_scanner'),(_)async=>{'path':'/tmp/scan.pdf','pages':3});
    await tester.pumpWidget(const ProviderScope(child:MaterialApp(home:ScanPdfScreen())));
    await tester.tap(find.text('Scan with camera'));await tester.pumpAndSettle();
    expect(find.text('3 pages ready'),findsOneWidget);expect(find.text('Save PDF'),findsOneWidget);
    expect(find.byType(TextField),findsOneWidget);expect(tester.takeException(),isNull);
  }, variant:TargetPlatformVariant.only(TargetPlatform.android));
  testWidgets('unavailable scanner retains gallery fallback',(tester)async{
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMethodCallHandler(const MethodChannel('com.hyzen.pharmd/document_scanner'),(_)async=>throw PlatformException(code:'scanner_unavailable',message:'Choose gallery images instead.'));
    await tester.pumpWidget(const ProviderScope(child:MaterialApp(home:ScanPdfScreen())));
    await tester.tap(find.text('Scan with camera'));await tester.pumpAndSettle();
    expect(find.text('Choose gallery images instead.'),findsOneWidget);expect(find.text('Choose gallery images'),findsOneWidget);
    expect(tester.takeException(),isNull);
  }, variant:TargetPlatformVariant.only(TargetPlatform.android));
  test('layered and flattened operations reach distinct native modes',()async{
    final calls=<MethodCall>[];
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMethodCallHandler(const MethodChannel('com.hyzen.pharmd/pdf_studio'),(call)async{calls.add(call);return '/tmp/result.pdf';});
    await StudioPdfEngine.compose([StudioPage('/tmp/a.pdf',0)]);
    await StudioPdfEngine.compose([StudioPage('/tmp/a.pdf',0)],flatten:true);
    expect(calls[0].arguments['flatten'],isFalse);expect(calls[1].arguments['flatten'],isTrue);
  });
  testWidgets('saving a scan persists workspace history and opens the saved PDF',(tester)async{
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMethodCallHandler(const MethodChannel('com.hyzen.pharmd/document_scanner'),(_)async=>{'path':'/tmp/scan.pdf','pages':3});
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMethodCallHandler(const MethodChannel('com.hyzen.pharmd/pdf_studio'),(_)async=>3);
    final container=ProviderContainer(overrides:[studioStorageProvider.overrideWithValue(_ScanStorage())]);addTearDown(container.dispose);
    final router=GoRouter(routes:[GoRoute(path:'/',builder:(c,_)=>Scaffold(body:TextButton(onPressed:()=>Navigator.of(c).push(MaterialPageRoute<void>(builder:(_)=>const ScanPdfScreen())),child:const Text('Create PDF')))),GoRoute(path:'/pdf-studio/viewer/:id',builder:(_,__)=>const Scaffold(body:Text('Saved PDF opened')))]);addTearDown(router.dispose);
    await tester.pumpWidget(UncontrolledProviderScope(container:container,child:MaterialApp.router(routerConfig:router)));
    await tester.tap(find.text('Create PDF'));await tester.pumpAndSettle();
    await tester.tap(find.text('Scan with camera'));await tester.pumpAndSettle();
    await tester.ensureVisible(find.text('Save PDF'));
    await tester.runAsync(()async{
      await tester.tap(find.text('Save PDF'));
      for(var i=0;i<100;i++){
        await Future<void>.delayed(const Duration(milliseconds:10));
        if(router.routeInformationProvider.value.uri.path.startsWith('/pdf-studio/viewer/'))break;
      }
    });
    await tester.pumpAndSettle();
    final saved=container.read(pdfStudioHistoryProvider).single;
    expect(saved.operationBadge,'SCANNED');expect(saved.pageCount,3);expect(saved.displayName,'Scanned notes.pdf');
    expect(find.text('Saved PDF opened'),findsOneWidget);expect(tester.takeException(),isNull);
  },variant:TargetPlatformVariant.only(TargetPlatform.android));
  testWidgets('document writer supports narrow phone formatting blocks',(tester)async{
    tester.view.physicalSize=const Size(320,900);tester.view.devicePixelRatio=1;
    addTearDown(tester.view.resetPhysicalSize);addTearDown(tester.view.resetDevicePixelRatio);
    await tester.pumpWidget(const ProviderScope(child:MaterialApp(home:RichDocumentScreen())));
    await tester.pumpAndSettle();
    expect(find.text('Document writer'),findsOneWidget);expect(find.byTooltip('Bold'),findsWidgets);
    expect(tester.takeException(),isNull);
  }, variant:TargetPlatformVariant.only(TargetPlatform.android));
}

