import 'dart:async';
import 'dart:typed_data';
import 'dart:math' as math;

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../core/widgets/common.dart';
import '../data/pdf_studio_repository.dart';
import '../data/studio_file_item.dart';
import '../data/studio_pdf_engine.dart';

enum _MarkTool {
  select,
  arrow,
  note,
  ink,
  highlight,
  underline,
  strike,
  rectangle,
  circle,
  text,
  signature,
}

class StudioAnnotationScreen extends ConsumerStatefulWidget {
  const StudioAnnotationScreen({super.key, required this.file});
  final StudioFileItem file;

  @override
  ConsumerState<StudioAnnotationScreen> createState() =>
      _StudioAnnotationScreenState();
}

class _StudioAnnotationScreenState
    extends ConsumerState<StudioAnnotationScreen> {
  Map<String, List<Map<String, dynamic>>> _all = {};
  ({Uint8List bytes, int width, int height})? _image;
  final _pending = <Offset>[];
  int _page = 1;
  int _total = 0;
  int _color = 0xFF6D35D4;
  double _stroke = 3;
  _MarkTool _tool = _MarkTool.ink;
  bool _working = true;
  int? _selected;
  Offset? _dragPoint;

  void _selectMark(Offset point) {
    _selected = null;
    for (var i = _marks.length-1; i >= 0; i--) {
      final raw = _marks[i]['points'] as List? ?? const [];
      final points = [for(final p in raw) if(p is List && p.length==2) Offset((p[0] as num).toDouble(),(p[1] as num).toDouble())];
      if(points.isEmpty) continue;
      final left=points.map((p)=>p.dx).reduce((a,b)=>a<b?a:b)-.04;
      final top=points.map((p)=>p.dy).reduce((a,b)=>a<b?a:b)-.04;
      final right=points.map((p)=>p.dx).reduce((a,b)=>a>b?a:b)+.15;
      final bottom=points.map((p)=>p.dy).reduce((a,b)=>a>b?a:b)+.05;
      if(Rect.fromLTRB(left,top,right,bottom).contains(point)){_selected=i;break;}
    }
  }

  List<Map<String, dynamic>> get _marks => _all.putIfAbsent('$_page', () => []);

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _load());
  }

  Future<void> _load() async {
    try {
      final results = await Future.wait<dynamic>([
        StudioPdfEngine.pageCount(widget.file.internalFilePath),
        StudioPdfEngine.readAnnotations(widget.file.editStateJsonPath),
      ]);
      _all = results[1] as Map<String, List<Map<String, dynamic>>>;
      _total = results[0] as int;
      await _showPage();
    } catch (e) {
      if (mounted) {
        setState(() => _working = false);
        showHSnack(
          context,
          'Annotation editor could not open: $e',
          error: true,
        );
      }
    }
  }

  Future<void> _showPage() async {
    if (mounted) setState(() => _working = true);
    try {
      _selected = null;
      final result = await StudioPdfEngine.renderPage(
        widget.file.internalFilePath,
        _page - 1,
      );
      if (mounted) {
        setState(() {
          _image = (
            bytes: result.bytes,
            width: result.width,
            height: result.height,
          );
          _pending.clear();
          _working = false;
        });
      }
    } catch (e) {
      if (mounted) {
        setState(() => _working = false);
        showHSnack(context, 'Page could not render: $e', error: true);
      }
    }
  }

  Future<void> _save() async {
    await StudioPdfEngine.writeAnnotations(widget.file.editStateJsonPath, _all);
    await ref
        .read(pdfStudioHistoryProvider.notifier)
        .markEdited(widget.file.id);
  }

  Future<void> _persist() async {
    try {
      await _save();
    } catch (e) {
      if (mounted) {
        showHSnack(context, 'Could not save page edits: $e', error: true);
      }
    }
  }

  Offset _normalized(Offset point, Size size) => Offset(
    (point.dx / size.width).clamp(0.0, 1.0).toDouble(),
    (point.dy / size.height).clamp(0.0, 1.0).toDouble(),
  );

  void _finishStroke() {
    if (_pending.isEmpty) return;
    if (_marks.length >= 100) {
      setState(() => _pending.clear());
      showHSnack(context, 'This page has reached the edit limit.', error: true);
      return;
    }
    setState(() {
      _marks.add({
        'tool': _tool.name,
        'points': [
          for (final point in _pending) [point.dx, point.dy],
        ],
        'color': _color,
        'stroke': _stroke,
      });
      _pending.clear();
    });
    unawaited(_persist());
  }

  Future<void> _placeText(Offset point) async {
    final controller = TextEditingController();
    final value = await showDialog<String>(
      context: context,
      builder: (dialog) => AlertDialog(
        title: Text(
          _tool == _MarkTool.signature ? 'Typed signature' : 'Page text note',
        ),
        content: TextField(
          controller: controller,
          autofocus: true,
          maxLength: 90,
          decoration: const InputDecoration(hintText: 'Write on this page'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialog),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialog, controller.text),
            child: const Text('Place'),
          ),
        ],
      ),
    );
    controller.dispose();
    if (value == null || value.trim().isEmpty || !mounted) return;
    if (_marks.length >= 100) {
      showHSnack(context, 'This page has reached the edit limit.', error: true);
      return;
    }
    setState(
      () => _marks.add({
        'tool': _tool.name,
        'points': [
          [point.dx, point.dy],
        ],
        'color': _color,
        'stroke': _stroke,
        'text': value.trim(),
      }),
    );
    await _persist();
  }

  Future<void> _export() async {
    setState(() => _working = true);
    try {
      await _save();
      final source = widget.file;
      final pages = [
        for (var index = 0; index < _total; index++)
          StudioPage(
            source.internalFilePath,
            index,
            annotations: _all['${index + 1}'] ?? const [],
          ),
      ];
      final path = await StudioPdfEngine.compose(pages);
      final name = source.displayName.replaceFirst(
        RegExp(r'\.pdf$', caseSensitive: false),
        ' annotated.pdf',
      );
      final output = await ref
          .read(pdfStudioHistoryProvider.notifier)
          .importFile(
            path,
            originalFileName: name,
            sourceType: 'CREATED',
            operationBadge: 'EDITED',
          );
      if (mounted) {
        final router = GoRouter.of(context);
        Navigator.of(context).pop();
        router.push('/pdf-studio/viewer/${output.id}');
      }
    } catch (e) {
      if (mounted) {
        showHSnack(context, 'Could not export annotated PDF: $e', error: true);
      }
    } finally {
      if (mounted) setState(() => _working = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final image = _image;
    final theme = Theme.of(context);
    return Scaffold(
      appBar: AppBar(
        title: Text('Annotate · ${widget.file.displayName}', maxLines: 1),
        actions: [
          IconButton(
            tooltip: _selected == null ? 'Undo last mark' : 'Delete selected mark',
            onPressed: _marks.isEmpty
                ? null
                : () {
                    setState(() { if(_selected != null && _selected! < _marks.length) { _marks.removeAt(_selected!); _selected=null; } else { _marks.removeLast(); } });
                    unawaited(_persist());
                  },
            icon: const Icon(Icons.undo_rounded),
          ),
          IconButton(
            tooltip: 'Save edit layer',
            onPressed: _working
                ? null
                : () async {
                    try {
                      await _save();
                      if (context.mounted) showHSnack(context, 'Edits saved');
                    } catch (e) {
                      if (context.mounted) {
                        showHSnack(
                          context,
                          'Could not save edits: $e',
                          error: true,
                        );
                      }
                    }
                  },
            icon: const Icon(Icons.save_outlined),
          ),
        ],
      ),
      body: Column(
        children: [
          if (_working) const LinearProgressIndicator(),
          if(_tool==_MarkTool.select) Padding(padding:const EdgeInsets.all(8),child:Text(_selected==null?'Tap a mark to select it, then drag to move.':'Selected · drag to move, or delete using the top button.')),
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            padding: const EdgeInsets.all(8),
            child: Row(
              children: [
                for (final tool in _MarkTool.values)
                  Padding(
                    padding: const EdgeInsets.only(right: 5),
                    child: ChoiceChip(
                      label: Text(tool.name),
                      selected: _tool == tool,
                      onSelected: (_) => setState(() => _tool = tool),
                    ),
                  ),
              ],
            ),
          ),
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: Row(
              children: [
                for (final color in [
                  0xFF6D35D4,
                  0xFFEF4978,
                  0xFF10886D,
                  0xFFE59A22,
                  0xFF18203B,
                ])
                  IconButton(
                    tooltip: 'Ink color',
                    onPressed: () => setState(() => _color = color),
                    icon: Icon(
                      _color == color ? Icons.circle : Icons.circle_outlined,
                      color: Color(color),
                    ),
                  ),
                const Text('Width'),
                SizedBox(
                  width: 100,
                  child: Slider(
                    value: _stroke,
                    min: 1,
                    max: 10,
                    onChanged: (v) => setState(() => _stroke = v),
                  ),
                ),
              ],
            ),
          ),
          Expanded(
            child: _working || image == null
                ? const Center(child: CircularProgressIndicator())
                : LayoutBuilder(
                    builder: (context, constraints) {
                      final width =
                          constraints.maxWidth <
                              constraints.maxHeight * image.width / image.height
                          ? constraints.maxWidth
                          : constraints.maxHeight * image.width / image.height;
                      final height = width * image.height / image.width;
                      final size = Size(width, height);
                      return Center(
                        child: SizedBox(
                          width: width,
                          height: height,
                          child: GestureDetector(
                            behavior: HitTestBehavior.opaque,
                            onPanStart:
                                (_tool == _MarkTool.text ||
                                    _tool == _MarkTool.signature || _tool == _MarkTool.note)
                                ? null
                                : (d) {
                                    if(_tool==_MarkTool.select) {setState((){_selectMark(_normalized(d.localPosition,size));_dragPoint=_normalized(d.localPosition,size);});return;}
                                    setState(
                                      () => _pending
                                        ..clear()
                                        ..add(
                                          _normalized(d.localPosition, size),
                                        ),
                                    );
                                  },
                            onPanUpdate:
                                (_tool == _MarkTool.text ||
                                    _tool == _MarkTool.signature || _tool == _MarkTool.note)
                                ? null
                                : (d) {
                                    final point = _normalized(
                                      d.localPosition,
                                      size,
                                    );
                                    if(_tool==_MarkTool.select) {
                                      if(_selected!=null && _dragPoint!=null) { final delta=point-_dragPoint!;setState((){final mark=Map<String,dynamic>.from(_marks[_selected!]);mark['points']=[for(final p in mark['points'] as List) [((p[0] as num).toDouble()+delta.dx).clamp(0.0,1.0),((p[1] as num).toDouble()+delta.dy).clamp(0.0,1.0)]];_marks[_selected!]=mark;_dragPoint=point;});}return;
                                    }
                                    setState(() {
                                      if (_tool == _MarkTool.rectangle || _tool==_MarkTool.arrow ||
                                          _tool == _MarkTool.circle ||
                                          _tool == _MarkTool.underline ||
                                          _tool == _MarkTool.strike) {
                                        if (_pending.length == 1) {
                                          _pending.add(point);
                                        } else {
                                          _pending[1] = point;
                                        }
                                      } else if (_pending.length < 250 &&
                                          (_pending.isEmpty ||
                                              (point - _pending.last).distance >
                                                  .003)) {
                                        _pending.add(point);
                                      }
                                    });
                                  },
                            onPanEnd: (_) { if(_tool==_MarkTool.select){unawaited(_persist());}else{_finishStroke();} },
                            onTapDown:
                                (_tool == _MarkTool.text ||
                                    _tool == _MarkTool.signature || _tool == _MarkTool.note)
                                ? (details) => _placeText(
                                    _normalized(details.localPosition, size),
                                  )
                                : _tool==_MarkTool.select ? (d)=>setState(()=>_selectMark(_normalized(d.localPosition,size))) : null,
                            child: Stack(
                              fit: StackFit.expand,
                              children: [
                                Image.memory(image.bytes, fit: BoxFit.fill),
                                CustomPaint(
                                  painter: _MarksPainter(
                                    _marks,
                                    _pending,
                                    _tool,
                                    _color,
                                    _stroke,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      );
                    },
                  ),
          ),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 5),
            child: Row(
              children: [
                IconButton(
                  tooltip: 'Previous page',
                  onPressed: _working || _page <= 1
                      ? null
                      : () {
                          _page--;
                          _showPage();
                        },
                  icon: const Icon(Icons.chevron_left),
                ),
                Expanded(
                  child: Text(
                    'Page $_page / $_total',
                    textAlign: TextAlign.center,
                    style: theme.textTheme.titleMedium,
                  ),
                ),
                IconButton(
                  tooltip: 'Next page',
                  onPressed: _working || _page >= _total
                      ? null
                      : () {
                          _page++;
                          _showPage();
                        },
                  icon: const Icon(Icons.chevron_right),
                ),
              ],
            ),
          ),
          SafeArea(
            top: false,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(12, 4, 12, 8),
              child: SizedBox(
                width: double.infinity,
                child: FilledButton.icon(
                  onPressed: _working ? null : _export,
                  icon: const Icon(Icons.picture_as_pdf_rounded),
                  label: const Text('Export annotated PDF copy'),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _MarksPainter extends CustomPainter {
  _MarksPainter(this.marks, this.pending, this.tool, this.color, this.stroke);
  final List<Map<String, dynamic>> marks;
  final List<Offset> pending;
  final _MarkTool tool;
  final int color;
  final double stroke;

  @override
  void paint(Canvas canvas, Size size) {
    for (final mark in marks) {
      _draw(canvas, size, mark);
    }
    if (pending.isNotEmpty) {
      _draw(canvas, size, {
        'tool': tool.name,
        'points': [
          for (final p in pending) [p.dx, p.dy],
        ],
        'color': color,
        'stroke': stroke,
      });
    }
  }

  void _draw(Canvas canvas, Size size, Map<String, dynamic> mark) {
    final points = <Offset>[];
    for (final raw in mark['points'] as List? ?? const []) {
      if (raw is List && raw.length == 2 && raw[0] is num && raw[1] is num) {
        points.add(
          Offset(
            (raw[0] as num).toDouble() * size.width,
            (raw[1] as num).toDouble() * size.height,
          ),
        );
      }
    }
    if (points.isEmpty) return;
    final type = mark['tool'] as String? ?? 'ink';
    final paint = Paint()
      ..color = Color(
        mark['color'] as int? ?? 0xFF6D35D4,
      ).withValues(alpha: type == 'highlight' ? .36 : 1)
      ..style = PaintingStyle.stroke
      ..strokeWidth =
          (mark['stroke'] as num? ?? 3).toDouble() *
          (type == 'highlight' ? 5 : 1)
      ..strokeCap = StrokeCap.round;
    final first = points.first;
    final last = points.last;
    if (type == 'rectangle' || type == 'circle') {
      final rect = Rect.fromPoints(first, last);
      if (type == 'rectangle') {
        canvas.drawRect(rect, paint);
      } else {
        canvas.drawOval(rect, paint);
      }
    } else if (type == 'text' || type == 'signature' || type == 'note') {
      final tp = TextPainter(
        text: TextSpan(
          text: mark['text'] as String? ?? '',
          style: TextStyle(
            color: paint.color,
            fontSize: type == 'signature' ? 24 : 14,
            fontStyle: type == 'signature'
                ? FontStyle.italic
                : FontStyle.normal,
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout(maxWidth: size.width - first.dx);
      tp.paint(canvas, first);
    } else {
      final path = Path()..moveTo(first.dx, first.dy);
      for (final point in points.skip(1)) {
        path.lineTo(point.dx, point.dy);
      }
      canvas.drawPath(path, paint);
      if(type=='arrow') {
        final angle=math.atan2(last.dy-first.dy,last.dx-first.dx);
        final head=math.max(10.0,paint.strokeWidth*4);
        canvas.drawLine(last,last-Offset(math.cos(angle-.5)*head,math.sin(angle-.5)*head),paint);
        canvas.drawLine(last,last-Offset(math.cos(angle+.5)*head,math.sin(angle+.5)*head),paint);
      }
    }
  }

  @override
  bool shouldRepaint(covariant _MarksPainter old) => true;
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../core/utils/media_upload.dart';
import '../../../core/widgets/common.dart';
import '../data/pdf_studio_repository.dart';
import '../data/studio_file_item.dart';
import '../data/studio_pdf_engine.dart';
import 'studio_page_thumbnail.dart';

enum StudioTool { open, merge, split, organize, images, document }

class StudioToolsScreen extends ConsumerStatefulWidget {
  const StudioToolsScreen({super.key, required this.tool, this.initialFile});
  final StudioTool tool;
  final StudioFileItem? initialFile;

  @override
  ConsumerState<StudioToolsScreen> createState() => _StudioToolsScreenState();
}

class _StudioToolsScreenState extends ConsumerState<StudioToolsScreen> {
  final _title = TextEditingController();
  final _text = TextEditingController();
  final _range = TextEditingController();
  final _chunk = TextEditingController(text: '5');
  final _sources = <PickedStudioFile>[];
  final _pages = <StudioPage>[];
  final _splitSelected = <int>{};
  bool _busy = false;

  String get _heading => switch (widget.tool) {
    StudioTool.open => 'Open PDF or document',
    StudioTool.merge => 'Merge PDFs',
    StudioTool.split => 'Split or extract pages',
    StudioTool.organize => 'Organize pages',
    StudioTool.images => 'Images to PDF',
    StudioTool.document => 'Document writer',
  };

  @override
  void initState() {
    super.initState();
    final file = widget.initialFile;
    if (file != null) {
      _title.text = file.displayName.replaceFirst(RegExp(r'\.[^.]+$'), ' copy');
      WidgetsBinding.instance.addPostFrameCallback(
        (_) => _work(() async {
          if (widget.tool == StudioTool.document) {
            final text = await StudioPdfEngine.readText(file.internalFilePath);
            if (mounted) _text.text = text;
          } else {
            await _addPaths([
              PickedStudioFile(file.displayName, file.internalFilePath),
            ]);
          }
        }),
      );
    }
  }

  @override
  void dispose() {
    _title.dispose();
    _text.dispose();
    _range.dispose();
    _chunk.dispose();
    super.dispose();
  }

  Future<void> _work(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } catch (e) {
      if (mounted) {
        showHSnack(
          context,
          'Could not complete this operation. Please retry.',
          error: true,
        );
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _chooseHistory() async {
    final available=ref.read(pdfStudioHistoryProvider).where((f)=>f.internalFilePath.toLowerCase().endsWith('.pdf')).toList();
    final selected=<String>{};
    final picked=await showModalBottomSheet<List<PickedStudioFile>>(context:context,isScrollControlled:true,showDragHandle:true,builder:(c)=>StatefulBuilder(builder:(c,update)=>SafeArea(child:SizedBox(height:MediaQuery.sizeOf(c).height*.7,child:Column(children:[
      const ListTile(title:Text('Choose from PDF Studio')),
      Expanded(child:available.isEmpty?const Center(child:Text('No PDFs in your workspace yet.')):ListView(children:[for(final file in available)CheckboxListTile(title:Text(file.displayName),value:selected.contains(file.id),onChanged:(v)=>update((){if(widget.tool!=StudioTool.merge)selected.clear();if(v==true){selected.add(file.id);}else{selected.remove(file.id);}}))])),
      Padding(padding:const EdgeInsets.all(12),child:FilledButton(onPressed:selected.isEmpty?null:()=>Navigator.pop(c,[for(final f in available)if(selected.contains(f.id))PickedStudioFile(f.displayName,f.internalFilePath)]),child:const Text('Use selected PDFs'))),
    ])))));
    if(picked!=null && mounted)await _work(()=>_addPaths(picked));
  }

  Future<void> _pick() => _work(() async {
    final picked = await StudioPdfEngine.pickFiles();
    if (picked.isNotEmpty) await _addPaths(picked);
  });

  Future<void> _addPaths(
    List<PickedStudioFile> picked, {
    bool replace = false,
  }) async {
    if (!mounted) return;
    if (widget.tool == StudioTool.open) {
      final chosen = picked.first;
      final item = await ref
          .read(pdfStudioHistoryProvider.notifier)
          .importFile(chosen.path, originalFileName: chosen.name);
      if (mounted) _openSaved(item.id);
      return;
    }
    final selected = (widget.tool == StudioTool.merge || widget.tool == StudioTool.images)
        ? (replace ? picked : [..._sources, ...picked]) : [picked.first];
    if (widget.tool == StudioTool.images) {
      if (selected.any(
        (f) => !RegExp(
          r'\.(jpe?g|png|webp)$',
          caseSensitive: false,
        ).hasMatch(f.name),
      )) {
        throw const FormatException('Select images only.');
      }
      setState(
        () => _sources
          ..clear()
          ..addAll(selected),
      );
      return;
    }
    if (selected.any((f) => !f.name.toLowerCase().endsWith('.pdf'))) {
      throw const FormatException('Select PDF files only.');
    }
    final pages = <StudioPage>[];
    for (final source in selected) {
      final count = await StudioPdfEngine.pageCount(source.path);
      if (count > 150 || count + pages.length > 150) {
        throw const FormatException('The maximum is 150 pages per operation.');
      }
      for (var index = 0; index < count; index++) {
        pages.add(StudioPage(source.path, index));
      }
    }
    if (mounted) {
      setState(() {
        _sources
          ..clear()
          ..addAll(selected);
        _pages
          ..clear()
          ..addAll(pages);
        _splitSelected.clear();
      });
    }
  }

  Future<StudioFileItem> _save(String path, String name, String badge) => ref
      .read(pdfStudioHistoryProvider.notifier)
      .importFile(
        path,
        originalFileName: name,
        sourceType: badge,
        operationBadge: badge,
      );

  Future<void> _finish(String path, String name, String badge) async {
    final item = await _save(path, name, badge);
    if (name.toLowerCase().endsWith('.pdf')) {
      final count = await StudioPdfEngine.pageCount(item.internalFilePath);
      await ref
          .read(pdfStudioHistoryProvider.notifier)
          .updatePageCount(item.id, count);
    }
    if (mounted) _openSaved(item.id);
  }

  void _openSaved(String id) {
    final router = GoRouter.of(context);
    Navigator.of(context).pop();
    router.push('/pdf-studio/viewer/$id');
  }

  List<int> _parseRange(String input, int count) {
    final result = <int>{};
    for (final part in input.split(',')) {
      final match = RegExp(r'^\s*(\d+)\s*(?:-\s*(\d+)\s*)?$').firstMatch(part);
      if (match == null) {
        throw const FormatException('Use page numbers such as 1-3, 5, 8-10.');
      }
      final first = int.parse(match.group(1)!);
      final last = int.tryParse(match.group(2) ?? '') ?? first;
      if (first < 1 || last > count || last < first) {
        throw const FormatException('Page range is outside this PDF.');
      }
      for (var page = first; page <= last; page++) {
        result.add(page - 1);
      }
    }
    return result.toList()..sort();
  }

  Future<void> _create() => _work(() async {
    final name = _title.text.trim().isEmpty
        ? 'Studio document'
        : _title.text.trim();
    switch (widget.tool) {
      case StudioTool.open:
        await _pick();
        break;
      case StudioTool.merge:
        if (_sources.length < 2) {
          throw const FormatException('Select at least two PDFs.');
        }
        await _finish(
          await StudioPdfEngine.compose(_pages),
          '$name.pdf',
          'MERGED',
        );
        break;
      case StudioTool.organize:
        if (_pages.isEmpty) throw const FormatException('Select pages first.');
        await _finish(
          await StudioPdfEngine.compose(_pages),
          '$name.pdf',
          'EDITED',
        );
        break;
      case StudioTool.split:
        if (_pages.isEmpty) throw const FormatException('Select a PDF first.');
        final selected = _splitSelected.isEmpty ? _parseRange(_range.text, _pages.length) : (_splitSelected.toList()..sort());
        await _finish(
          await StudioPdfEngine.compose([for (final i in selected) _pages[i]]),
          '$name.pdf',
          'SPLIT',
        );
        break;
      case StudioTool.images:
        if (_sources.isEmpty) {
          throw const FormatException('Choose images first.');
        }
        await _finish(
          await StudioPdfEngine.imagesToPdf([
            for (final file in _sources) file.path,
          ]),
          '$name.pdf',
          'CREATED',
        );
        break;
      case StudioTool.document:
        if (_text.text.trim().isEmpty) {
          throw const FormatException('Write some text first.');
        }
        final path = await StudioPdfEngine.textFile(_text.text);
        await _finish(path, '$name.txt', 'CREATED');
        break;
    }
  });

  Future<void> _splitEvery() => _work(() async {
    final n = int.tryParse(_chunk.text);
    if (_pages.isEmpty || n == null || n < 1 || n > 150) {
      throw const FormatException('Choose a PDF and a valid page count.');
    }
    final name = _title.text.trim().isEmpty ? 'Extract' : _title.text.trim();
    var part = 0;
    for (var start = 0; start < _pages.length; start += n) {
      part++;
      final end = start + n > _pages.length ? _pages.length : start + n;
      final output = await StudioPdfEngine.compose(_pages.sublist(start, end));
      await _save(output, '$name $part.pdf', 'SPLIT');
    }
    if (mounted) {
      showHSnack(context, '$part PDFs saved in Studio');
      Navigator.pop(context);
    }
  });

