class ScanPdfScreen extends ConsumerStatefulWidget {
  const ScanPdfScreen({super.key});
  @override
  ConsumerState<ScanPdfScreen> createState() => _ScanPdfScreenState();
}

class _ScanPdfScreenState extends ConsumerState<ScanPdfScreen> {
  final _name = TextEditingController(text: 'Scanned notes');
  bool _busy = false;
  String? _path;
  int _pages = 0;
  String? _error;
  @override
  void dispose() { _name.dispose(); super.dispose(); }

  Future<void> _scan() async {
    setState(() { _busy = true; _error = null; });
    try {
      final result = await const MethodChannel('com.hyzen.pharmd/document_scanner')
          .invokeMapMethod<String, dynamic>('scan');
      if (!mounted || result == null) return;
      setState(() { _path = result['path'] as String; _pages = result['pages'] as int; });
    } on PlatformException catch (e) {
      if (mounted) setState(() => _error = e.message ?? 'Scanner unavailable. Choose images below.');
    } catch (_) {
      if (mounted) setState(() => _error = 'Scanner unavailable. Choose images below.');
    } finally { if (mounted) setState(() => _busy = false); }
  }

  Future<void> _save() async {
    if (_path == null || _busy) return;
    setState(() => _busy = true);
    try {
      final count = await StudioPdfEngine.pageCount(_path!);
      if (count < 1) throw const FormatException('Empty scan');
      final name = _name.text.trim().replaceFirst(RegExp(r'\.pdf$', caseSensitive: false), '');
      final item = await ref.read(pdfStudioHistoryProvider.notifier).importFile(
        _path!, originalFileName: '${name.isEmpty ? 'Scanned notes' : name}.pdf',
        sourceType: 'IMAGE_SCAN', operationBadge: 'SCANNED',
      );
      await ref.read(pdfStudioHistoryProvider.notifier).updatePageCount(item.id, count);
      if (!mounted) return;
      final router = GoRouter.of(context);
      Navigator.pop(context);
      router.push('/pdf-studio/viewer/${item.id}');
    } catch (_) {
      if (mounted) showHSnack(context, 'Could not save this PDF. Try again.', error: true);
    } finally { if (mounted) setState(() => _busy = false); }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final android = !kIsWeb && defaultTargetPlatform == TargetPlatform.android;
    return Scaffold(
      appBar: AppBar(title: const Text('Create PDF')),
      body: ListView(padding: const EdgeInsets.all(20), children: [
        Container(padding: const EdgeInsets.all(24),
          decoration: BoxDecoration(color: theme.colorScheme.primaryContainer, borderRadius: BorderRadius.circular(26)),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Icon(Icons.document_scanner_rounded, size: 54, color: theme.colorScheme.primary),
            const SizedBox(height: 16),
            Text('Paper to PDF', style: theme.textTheme.headlineSmall),
            const SizedBox(height: 8),
            const Text('Scan notes, crop edges and arrange your pages.'),
          ])),
        const SizedBox(height: 20),
        if (android) FilledButton.icon(onPressed: _busy ? null : _scan,
          icon: const Icon(Icons.camera_alt_rounded), label: Text(_path == null ? 'Scan with camera' : 'Scan again')),
        OutlinedButton.icon(onPressed: _busy ? null : () => Navigator.push(context,
          MaterialPageRoute<void>(builder: (_) => const StudioToolsScreen(tool: StudioTool.images))),
          icon: const Icon(Icons.photo_library_outlined), label: const Text('Choose gallery images')),
        if (android && _path == null) Padding(padding: const EdgeInsets.symmetric(vertical: 8),
          child: Text('First scan may need a one-time scanner download.', style: theme.textTheme.bodySmall)),
        if (_error != null) Padding(padding: const EdgeInsets.symmetric(vertical: 12),
          child: Text(_error!, style: TextStyle(color: theme.colorScheme.error))),
        if (_path != null) ...[
          const SizedBox(height: 24),
          ListTile(contentPadding: EdgeInsets.zero, leading: const Icon(Icons.task_alt_rounded),
            title: Text('$_pages pages ready'), subtitle: const Text('Save in PDF Studio, then share or Save As.')),
          TextField(controller: _name, maxLength: 100, decoration: const InputDecoration(labelText: 'PDF name')),
          FilledButton.icon(onPressed: _busy ? null : _save, icon: const Icon(Icons.picture_as_pdf_rounded), label: const Text('Save PDF')),
        ],
        if (_busy) const Padding(padding: EdgeInsets.all(20), child: LinearProgressIndicator()),
      ]),
    );
  }
}

